FROM (VALUES
  ('Waist-Length Knotless Box Braids', 'Painless, tension-free knotless box braids for girls and women. Seamless root extensions offering weightless comfort and fluid natural movement.', 'Braids & Cornrows', 'Women & Girls (Braids)', 'https://i.ibb.co/cXxD5MpB/Chat-GPT-Image-6-sept-2026-15-56-42.png', 'mika', 0),
  ('Swirl Cornrows & Geometric Spiral Braids', 'Intricate swirl pattern cornrows flowing around the crown with zero frizz, calibrated scalp tension, and nourishing hydration finish.', 'Braids & Cornrows', 'Women & Girls (Braids)', 'https://i.ibb.co/xq8zMm2t/Chat-GPT-Image-6-sept-2026-15-55-41.png', 'mika', 10),
  ('Sleek High Braided Ponytail & Cornrow Crown', 'High braided ponytail anchored with precision geometric scalp braids and high-gloss conditioning finish for everyday style or special events.', 'Braids & Cornrows', 'Women & Girls (Braids)', 'https://i.ibb.co/d4N6qCDJ/Chat-GPT-Image-Sep-6-2026-03-39-13-PM-1.png', 'mika', 20),
  ('Burgundy Goddess Locs & Edge Styling', 'Bohemian goddess locs in rich burgundy with loose spiral curl tendrils and sculpted baby-hair waves with organic botanical gel.', 'Locs & Twists', 'Women & Girls (Braids)', 'https://i.ibb.co/zhXtNXB4/Chat-GPT-Image-Sep-6-2026-03-38-30-PM-1.png', 'mika', 30),
  ('Bohemian Soft Curls & Feed-In Braids', 'Lush bohemian feed-in braids accented with cascading soft curls and nourishing scalp oil.', 'Braids & Cornrows', 'Women & Girls (Braids)', 'https://images.unsplash.com/photo-1589156280159-27698a70f29e?auto=format&fit=crop&q=80&w=800', 'mika', 40),
  ('Precision Mid Skin Fade & Textured Top', 'Surgical zero-gap skin fade for boys and men. Optical blur transition from bare skin to textured top with crisp hairline razor edge.', 'Skin Fades', 'Men & Boys (Haircuts)', 'https://images.unsplash.com/photo-1622286342621-4bd786c2447c?auto=format&fit=crop&q=80&w=800', 'lusca', 50),
  ('Low Drop Fade & Structured Full Beard', 'Low curved drop fade contouring the ear and neckline, blended seamlessly into a sharply defined beard gradient.', 'Beards & Shaves', 'Men & Boys (Haircuts)', 'https://images.unsplash.com/photo-1503951914875-452162b0f3f1?auto=format&fit=crop&q=80&w=800', 'lusca', 60),
  ('Twisted Locs with High Taper Fade & Beard Lineup', 'High temple taper fade paired with sharp line work, sculpted beard definition, and hot eucalyptus towel finish.', 'Skin Fades', 'Men & Boys (Haircuts)', 'https://i.ibb.co/20Ns74Tz/Chat-GPT-Image-6-sept-2026-15-53-44.png', 'lusca', 70),
  ('Executive Razor Cut & Clean Nape', 'Classic executive shear work for men and boys with straight razor nape detailing and soothing talc finish.', 'Skin Fades', 'Men & Boys (Haircuts)', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=800', 'lusca', 80),
  ('Taper Fade & Waves for Boys & Men', 'Subtle temple and neck tapers preserving side density with high-definition wave polish.', 'Skin Fades', 'Men & Boys (Haircuts)', 'https://images.unsplash.com/photo-1599566150163-29194dcaad36?auto=format&fit=crop&q=80&w=800', 'lusca', 90),
  ('Final Stop Barbershop • Storefront & Lounge', 'Our modern grooming lounge located at 4748 University Ave, San Diego. Equipped with luxury hydraulic chairs and warm hospitality.', 'The Shop', 'Shop', 'https://i.ibb.co/HTWwwJNz/Chat-GPT-Image-Sep-6-2026-03-11-02-PM-1.png', NULL, 100)
) AS v(title, description, category, audience, image_url, member, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM public.gallery_items WHERE website_id = 'ws_d5e600b7dc2ec9a9');

INSERT INTO public.reviews (website_id, organization_id, author, rating, comment, source, team_member_id, sort_order, data)
SELECT 'ws_d5e600b7dc2ec9a9', 'd2d91733-77fe-4840-8a47-4564de49dd29', v.author, v.rating, v.comment, v.source,
  (SELECT id FROM public.team_members t WHERE t.website_id = 'ws_d5e600b7dc2ec9a9' AND t.slug = v.member), v.sort_order, v.data
FROM (VALUES
  ('Trevorn Kitt', 5, 'Even when it was near closing time, he still took me in without hesitation and gave me a full transformation. The attention to detail and professionalism were top-tier. He didn’t rush the cut at all — every line was clean and the fade was flawless. You can tell he takes real pride in his work. Highly recommend if you’re looking for a barber who delivers quality every time!', 'google', NULL, 0, '{"role":"Google Maps Review (2 avis)","barber_label":"Master Barber","date_label":"1 year ago","price":"$30–40","service":"Haircuts / Coupes de cheveux","is_local_guide":false}'::jsonb),
  ('Ivan Guevara', 5, 'Anthony really took his time to give me a fresh cut, dude is dedicated to his craft and it shows!!!', 'google', NULL, 10, '{"role":"Local Guide · 72 reviews · 6 photos","barber_label":"Anthony","date_label":"1 year ago","price":"$30–40","service":"Mid drop fade • Fades, tapers & braiding","is_local_guide":true}'::jsonb),
  ('Allen SamuelsClarence', 5, 'REGULAR BARBER 🔥 I’ve been looking for one for the past 2 years and finally found one … clean friendly ! Highly recommend', 'google', NULL, 20, '{"role":"Local Guide · 20 reviews · 12 photos","barber_label":"Final Stop Crew","date_label":"1 year ago","price":"$20–30","service":"Regular Cut","is_local_guide":true}'::jsonb),
  ('Marcus D.', 5, 'Mika is a true artist behind the chair and it shows in every minute. His fade transitions are insanely clean, the shop is spotless, and the energy is top tier.', 'google', NULL, 30, '{"role":"Regular Client (3 Years)","barber_label":"Mika","date_label":"2 days ago","price":"$45","service":"Signature Fade & Beard","is_local_guide":false}'::jsonb),
  ('Darnell W.', 5, 'Lusca is a true master of beard sculpting and hair textures. Masterful dedication reflected in calm precision and eucalyptus hot towel treatment. My braids and beard have never looked sharper.', 'google', NULL, 40, '{"role":"Regular Client","barber_label":"Lusca","date_label":"5 days ago","price":"$50","service":"Master Beard Sculpt & Haircut","is_local_guide":false}'::jsonb),
  ('Julian B.', 5, 'Visiting San Diego and stopped by Final Stop on a friend''s recommendation. Smooth online booking, great greeting, and razor-sharp straight razor detailing. 10/10.', 'google', NULL, 50, '{"role":"San Diego Visitor","barber_label":"Mika","date_label":"1 week ago","price":"$40","service":"Hot Towel Fade","is_local_guide":false}'::jsonb),
  ('Aaliyah M.', 5, 'Mika has over 20 years of experience and you feel it immediately. My knotless braids had zero pain or tension, and the parts are mathematically perfect!', 'client', 'mika', 100, '{"date_label":"3 days ago"}'::jsonb),
  ('Keisha T.', 5, 'Best braider in San Diego! Mika did my goddess locs for my sister''s wedding and I received compliments for weeks.', 'client', 'mika', 110, '{"date_label":"1 week ago"}'::jsonb),
  ('Marcus V.', 5, 'Lusca has over 20 years cutting hair and you see it right away. The skin fade is like an optical illusion and the razor lines are laser straight.', 'client', 'lusca', 100, '{"date_label":"5 days ago"}'::jsonb),
  ('Terrence K.', 5, 'Brought my son for his back-to-school taper and got my beard shaped. Lusca is patient, professional, and the best barber in San Diego.', 'client', 'lusca', 110, '{"date_label":"2 weeks ago"}'::jsonb)
) AS v(author, rating, comment, source, member, sort_order, data)
WHERE NOT EXISTS (SELECT 1 FROM public.reviews WHERE website_id = 'ws_d5e600b7dc2ec9a9');

INSERT INTO public.faq_items (website_id, organization_id, question, answer, sort_order)
SELECT 'ws_d5e600b7dc2ec9a9', 'd2d91733-77fe-4840-8a47-4564de49dd29', v.question, v.answer, v.sort_order
FROM (VALUES
  ('How far in advance should I book an appointment?', 'We recommend booking at least 24 to 48 hours in advance to secure your preferred time and barber, especially for Friday and Saturday slots.', 0),
  ('Do you accept walk-in clients?', 'Yes! Walk-ins are always welcome based on daily chair availability. You can also join our live same-day waitlist directly from the website to track your turn in real time.', 10),
  ('What grooming products do you use?', 'We exclusively formulate and use premium artisan grooming goods, natural eucalyptus steam balms, alcohol-free witch hazel toners, and certified organic beard oils gentle on all skin types.', 20),
  ('Can I cancel or reschedule my appointment?', 'Yes, you can reschedule or cancel your reservation free of charge up to 2 hours before your scheduled appointment time.', 30)
) AS v(question, answer, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM public.faq_items WHERE website_id = 'ws_d5e600b7dc2ec9a9');
